import type { JSX } from "solid-js"
import { createContext, splitProps, useContext } from "solid-js"
import type { TransformPoint } from "motion-utils"
import type { Transition } from "motion-dom"

export type ReducedMotionConfig = "always" | "never" | "user"

export interface MotionConfigContext {
  transformPagePoint: TransformPoint
  isStatic: boolean
  transition?: Transition
  reducedMotion?: ReducedMotionConfig
  nonce?: string
  skipAnimations?: boolean
}

const defaultContext: MotionConfigContext = {
  transformPagePoint: ((p) => p) as TransformPoint,
  isStatic: false,
  reducedMotion: "never",
}

export const MotionConfigContext = createContext<MotionConfigContext>(defaultContext)

export function MotionConfig(props: Partial<MotionConfigContext> & { children?: JSX.Element }) {
  const parent = useContext(MotionConfigContext)
  const [local, contextProps] = splitProps(props, ["children"])
  const value = { ...parent, ...contextProps }
  return <MotionConfigContext.Provider value={value}>{local.children}</MotionConfigContext.Provider>
}
