import {
  AnyResolvedKeyframe,
  mapValue,
  MotionValue,
  transform,
  TransformOptions,
  transformValue,
} from "motion-dom"
import { onCleanup } from "solid-js"

export type InputRange = number[]
type SingleTransformer<I, O> = (input: I) => O
type MultiTransformer<I, O> = (input: I[]) => O
type Transformer<I, O> =
  | SingleTransformer<I, O>
  | MultiTransformer<AnyResolvedKeyframe, O>

export function useTransform<I, O>(
  value: MotionValue<number>,
  inputRange: InputRange,
  outputRange: O[],
  options?: TransformOptions<O>,
): MotionValue<O>

export function useTransform<I, O>(
  input: MotionValue<I>,
  transformer: SingleTransformer<I, O>,
): MotionValue<O>

export function useTransform<I, O>(
  input:
    | MotionValue<string>[]
    | MotionValue<number>[]
    | MotionValue<AnyResolvedKeyframe>[],
  transformer: MultiTransformer<I, O>,
): MotionValue<O>

export function useTransform<I, O>(transformer: () => O): MotionValue<O>

export function useTransform<I, O>(
  input:
    | MotionValue<I>
    | MotionValue<string>[]
    | MotionValue<number>[]
    | MotionValue<AnyResolvedKeyframe>[]
    | (() => O),
  inputRangeOrTransformer?: InputRange | Transformer<I, O>,
  outputRange?: O[],
  options?: TransformOptions<O>,
): MotionValue<O> {
  if (typeof input === "function") {
    const value = transformValue(input)
    onCleanup(() => value.destroy())
    return value
  }

  let value: MotionValue<O>

  if (Array.isArray(input)) {
    const transformer =
      typeof inputRangeOrTransformer === "function"
        ? (inputRangeOrTransformer as MultiTransformer<AnyResolvedKeyframe, O>)
        : (transform(inputRangeOrTransformer as InputRange, outputRange as O[], options) as unknown as MultiTransformer<
            AnyResolvedKeyframe,
            O
          >)

    value = transformValue(() =>
      (transformer as MultiTransformer<AnyResolvedKeyframe, O>)(
        input.map((item) => item.get()) as AnyResolvedKeyframe[],
      ),
    )
  } else if (typeof inputRangeOrTransformer === "function") {
    const transformer = inputRangeOrTransformer as SingleTransformer<I, O>
    value = transformValue(() => transformer((input as MotionValue<I>).get()))
  } else {
    value = mapValue(
      input as unknown as MotionValue<number>,
      inputRangeOrTransformer as InputRange,
      outputRange as O[],
      options,
    )
  }

  onCleanup(() => value.destroy())
  return value
}
