import { setFeatureDefinitions } from "motion-dom"
import { getInitializedFeatureDefinitions } from "./definitions"

export function loadFeatures(features: Record<string, unknown>) {
  const featureDefinitions = getInitializedFeatureDefinitions() as any

  for (const key in features) {
    featureDefinitions[key] = {
      ...featureDefinitions[key],
      ...(features as any)[key],
    }
  }

  setFeatureDefinitions(featureDefinitions)
}
