import {
  AnimationScope,
  createGeneratorEasing,
  defaultOffset,
  DOMKeyframesDefinition,
  AnimationOptions as DynamicAnimationOptions,
  fillOffset,
  GeneratorFactory,
  isGenerator,
  isMotionValue,
  Transition,
  UnresolvedValueKeyframe,
  type AnyResolvedKeyframe,
  type MotionValue,
} from "motion-dom"
import { Easing, getEasingForSegment, invariant, progress, secondsToMilliseconds } from "motion-utils"
import { resolveSubjects } from "../animate/resolve-subjects"
import {
  AnimationSequence,
  At,
  ResolvedAnimationDefinitions,
  SequenceMap,
  SequenceOptions,
  ValueSequence,
} from "./types"
import { calculateRepeatDuration } from "./utils/calc-repeat-duration"
import { calcNextTime } from "./utils/calc-time"
import { addKeyframes } from "./utils/edit"
import { normalizeTimes } from "./utils/normalize-times"
import { compareByTime } from "./utils/sort"

const defaultSegmentEasing = "easeInOut"
const MAX_REPEAT = 20

export function createAnimationsFromSequence(
  sequence: AnimationSequence,
  { defaultTransition = {}, ...sequenceTransition }: SequenceOptions = {},
  scope?: AnimationScope,
  generators?: { [key: string]: GeneratorFactory },
): ResolvedAnimationDefinitions {
  const defaultDuration = defaultTransition.duration || 0.3
  const animationDefinitions: ResolvedAnimationDefinitions = new Map()
  const sequences = new Map<Element | MotionValue, SequenceMap>()
  const elementCache = {}
  const timeLabels = new Map<string, number>()

  let prevTime = 0
  let currentTime = 0
  let totalDuration = 0

  for (let i = 0; i < sequence.length; i++) {
    const segment = sequence[i]

    if (typeof segment === "string") {
      timeLabels.set(segment, currentTime)
      continue
    } else if (!Array.isArray(segment)) {
      timeLabels.set(segment.name, calcNextTime(currentTime, segment.at, prevTime, timeLabels))
      continue
    }

    let [subject, keyframes, transition = {}] = segment

    if (transition.at !== undefined) {
      currentTime = calcNextTime(currentTime, transition.at, prevTime, timeLabels)
    }

    let maxDuration = 0

    const resolveValueSequence = (
      valueKeyframes: UnresolvedValueKeyframe | UnresolvedValueKeyframe[],
      valueTransition: Transition | DynamicAnimationOptions,
      valueSequence: ValueSequence,
      elementIndex = 0,
      numSubjects = 0,
    ) => {
      const valueKeyframesAsList = keyframesAsList(valueKeyframes)
      const {
        delay = 0,
        times = defaultOffset(valueKeyframesAsList),
        type = defaultTransition.type || "keyframes",
        repeat,
        repeatType,
        repeatDelay = 0,
        ...remainingTransition
      } = valueTransition
      let { ease = defaultTransition.ease || "easeOut", duration } = valueTransition

      const calculatedDelay = typeof delay === "function" ? delay(elementIndex, numSubjects) : delay

      const numKeyframes = valueKeyframesAsList.length
      const createGenerator = isGenerator(type) ? type : generators?.[type || "keyframes"]

      if (numKeyframes <= 2 && createGenerator) {
        let absoluteDelta = 100
        if (numKeyframes === 2 && isNumberKeyframesArray(valueKeyframesAsList)) {
          const delta = valueKeyframesAsList[1] - valueKeyframesAsList[0]
          absoluteDelta = Math.abs(delta)
        }

        const springTransition = {
          ...defaultTransition,
          ...remainingTransition,
        }
        if (duration !== undefined) {
          springTransition.duration = secondsToMilliseconds(duration)
        }

        const springEasing = createGeneratorEasing(springTransition, absoluteDelta, createGenerator)

        ease = springEasing.ease
        duration = springEasing.duration
      }

      duration = duration ?? defaultDuration

      const startTime = currentTime + calculatedDelay

      if (times.length === 1 && times[0] === 0) {
        times[1] = 1
      }

      const remainder = times.length - valueKeyframesAsList.length
      remainder > 0 && fillOffset(times, remainder)

      valueKeyframesAsList.length === 1 && valueKeyframesAsList.unshift(null)

      if (repeat) {
        invariant(repeat < MAX_REPEAT, "Repeat count too high, must be less than 20", "repeat-count-high")

        duration = calculateRepeatDuration(duration ?? defaultDuration, repeat, repeatDelay)

        const originalKeyframes = [...valueKeyframesAsList]
        const originalTimes = [...times]
        ease = Array.isArray(ease) ? [...ease] : [ease]
        const originalEase = [...ease]

        for (let repeatIndex = 0; repeatIndex < repeat; repeatIndex++) {
          valueKeyframesAsList.push(...originalKeyframes)

          for (let keyframeIndex = 0; keyframeIndex < originalKeyframes.length; keyframeIndex++) {
            times.push(originalTimes[keyframeIndex] + (repeatIndex + 1))
            ease.push(keyframeIndex === 0 ? "linear" : getEasingForSegment(originalEase, keyframeIndex - 1))
          }
        }

        normalizeTimes(times, repeat)
      }

      const targetTime = startTime + (duration ?? defaultDuration)

      addKeyframes(valueSequence, valueKeyframesAsList, ease as Easing | Easing[], times, startTime, targetTime)

      maxDuration = Math.max(calculatedDelay + duration, maxDuration)
      totalDuration = Math.max(targetTime, totalDuration)
    }

    if (isMotionValue(subject)) {
      const subjectSequence = getSubjectSequence(subject, sequences)
      resolveValueSequence(keyframes as AnyResolvedKeyframe, transition, getValueSequence("default", subjectSequence))
    } else {
      const subjects = resolveSubjects(subject, keyframes as DOMKeyframesDefinition, scope, elementCache)

      const numSubjects = subjects.length

      for (let subjectIndex = 0; subjectIndex < numSubjects; subjectIndex++) {
        keyframes = keyframes as DOMKeyframesDefinition
        transition = transition as DynamicAnimationOptions

        const thisSubject = subjects[subjectIndex]
        const subjectSequence = getSubjectSequence(thisSubject, sequences)

        for (const key in keyframes) {
          resolveValueSequence(
            keyframes[key as keyof typeof keyframes] as UnresolvedValueKeyframe,
            getValueTransition(transition, key),
            getValueSequence(key, subjectSequence),
            subjectIndex,
            numSubjects,
          )
        }
      }
    }

    prevTime = currentTime
    currentTime += maxDuration
  }

  sequences.forEach((valueSequences, element) => {
    for (const key in valueSequences) {
      const valueSequence = valueSequences[key]
      valueSequence.sort(compareByTime)

      const keyframes: UnresolvedValueKeyframe[] = []
      const valueOffset: number[] = []
      const valueEasing: Easing[] = []

      for (let i = 0; i < valueSequence.length; i++) {
        const { at, value, easing } = valueSequence[i]
        keyframes.push(value)
        valueOffset.push(progress(0, totalDuration, at))
        valueEasing.push(easing || "easeOut")
      }

      if (valueOffset[0] !== 0) {
        valueOffset.unshift(0)
        keyframes.unshift(keyframes[0])
        valueEasing.unshift(defaultSegmentEasing)
      }

      if (valueOffset[valueOffset.length - 1] !== 1) {
        valueOffset.push(1)
        keyframes.push(null)
      }

      if (!animationDefinitions.has(element)) {
        animationDefinitions.set(element, {
          keyframes: {},
          transition: {},
        })
      }

      const definition = animationDefinitions.get(element)!
      definition.keyframes[key] = keyframes

      const { type: _type, ...remainingDefaultTransition } = defaultTransition
      definition.transition[key] = {
        ...remainingDefaultTransition,
        duration: totalDuration,
        ease: valueEasing,
        times: valueOffset,
        ...sequenceTransition,
      }
    }
  })

  return animationDefinitions
}

function getSubjectSequence<O extends {}>(
  subject: Element | MotionValue | O,
  sequences: Map<Element | MotionValue | O, SequenceMap>,
): SequenceMap {
  !sequences.has(subject) && sequences.set(subject, {})
  return sequences.get(subject)!
}

function getValueSequence(name: string, sequences: SequenceMap): ValueSequence {
  if (!sequences[name]) sequences[name] = []
  return sequences[name]
}

function keyframesAsList(keyframes: UnresolvedValueKeyframe | UnresolvedValueKeyframe[]): UnresolvedValueKeyframe[] {
  return Array.isArray(keyframes) ? keyframes : [keyframes]
}

export function getValueTransition(transition: DynamicAnimationOptions & At, key: string): DynamicAnimationOptions {
  return transition && (transition as any)[key]
    ? {
        ...transition,
        ...((transition as any)[key] as Transition),
      }
    : { ...transition }
}

const isNumber = (keyframe: unknown) => typeof keyframe === "number"
const isNumberKeyframesArray = (keyframes: UnresolvedValueKeyframe[]): keyframes is number[] =>
  keyframes.every(isNumber)
