import type { MotionProps } from "../../motion/types"
import { isValidMotionProp } from "../../motion/utils/valid-prop"

export function filterProps(props: MotionProps, isDom: boolean, forwardMotionProps: boolean) {
  const filteredProps: Record<string, unknown> = {}

  for (const key in props) {
    if (key === "values" && typeof (props as any).values === "object") continue

    if (
      !isValidMotionProp(key) ||
      (forwardMotionProps === true && isValidMotionProp(key)) ||
      (!isDom && !isValidMotionProp(key)) ||
      ((props as any).draggable && key.startsWith("onDrag"))
    ) {
      filteredProps[key] = (props as any)[key]
    }
  }

  return filteredProps
}
