import { DragGesture as UpstreamDragGesture } from "../../gestures/drag"
import { PanGesture } from "../../gestures/pan"
import { HoverGesture } from "../../gestures/hover"
import { PressGesture } from "../../gestures/press"
import { FocusGesture } from "../../gestures/focus"

class DragGesture extends UpstreamDragGesture {
  unmount() {
    // Solid disposal is final. Always release the window listeners and global
    // drag lock, including when an element is removed in the middle of a drag.
    this.controls.dispose()
    super.unmount()
  }
}

export const gestures = {
  drag: { Feature: DragGesture },
  pan: { Feature: PanGesture },
  hover: { Feature: HoverGesture },
  tap: { Feature: PressGesture },
  focus: { Feature: FocusGesture },
}
