import { buildSVGAttrs, isSVGTag } from "motion-dom"
import type { MotionProps } from "../../motion/types"
import type { ResolvedValues } from "../types"
import { copyRawValuesOnly } from "../html/use-props"
import { createSvgRenderState } from "./utils/create-render-state"
import { toSolidStyle } from "../dom/style"

export function resolveSVGProps(props: MotionProps, visualState: ResolvedValues, Component: string) {
  const state = createSvgRenderState()

  buildSVGAttrs(state, visualState, isSVGTag(Component), props.transformTemplate, props.style)

  const visualProps: Record<string, unknown> = {
    ...state.attrs,
    style: { ...state.style },
  }

  if (props.style) {
    const rawStyles: Record<string, unknown> = {}
    copyRawValuesOnly(rawStyles as any, props.style as any, props)
    ;(visualProps as any).style = { ...rawStyles, ...(visualProps as any).style }
  }

  const pathLength = (visualState as any).pathLength
  const pathSpacing = (visualState as any).pathSpacing
  const pathOffset = (visualState as any).pathOffset

  if (pathLength !== undefined) {
    const spacing = pathSpacing ?? 1 - Number(pathLength)
    ;(visualProps as any).pathLength = 1
    ;(visualProps as any)["stroke-dasharray"] = `${pathLength} ${spacing}`
    ;(visualProps as any)["stroke-dashoffset"] = `${-Number(pathOffset ?? 0)}`
  }

  visualProps.style = toSolidStyle(visualProps.style as Record<string, unknown>)
  return visualProps
}
