import {
  AnyResolvedKeyframe,
  isMotionValue,
  MotionValue,
  SpringOptions,
  cancelFrame,
  frame,
  JSAnimation,
  motionValue,
} from "motion-dom"
import { useContext } from "solid-js"
import { MotionConfigContext } from "../components/MotionConfig"
import { useTransform } from "./use-transform"
import { onCleanup } from "solid-js"

export function useSpring(source: MotionValue<string>, options?: SpringOptions): MotionValue<string>
export function useSpring(source: string, options?: SpringOptions): MotionValue<string>
export function useSpring(source: MotionValue<number>, options?: SpringOptions): MotionValue<number>
export function useSpring(source: number, options?: SpringOptions): MotionValue<number>
export function useSpring(
  source: MotionValue<string> | MotionValue<number> | AnyResolvedKeyframe,
  options: SpringOptions = {},
) {
  const { isStatic } = useContext(MotionConfigContext)
  const getFromSource = () => (isMotionValue(source) ? source.get() : source)

  if (isStatic) {
    return useTransform(getFromSource)
  }

  const initial = getFromSource() as string | number
  const value = motionValue(initial)
  const unit = typeof initial === "string" ? initial.replace(/[\d.-]/g, "") : ""
  const parse = (latest: string | number) => unit ? `${parseFloat(String(latest))}${unit}` : parseFloat(String(latest))
  let target = initial
  let setter: (value: string | number) => void
  let disposed = false
  const stop = () => {
    cancelFrame(start)
    value.stop()
  }
  // motion-dom's springValue queues an anonymous callback that survives
  // destroy(). Keep the scheduled work owned and cancellable by this Solid scope.
  const start = () => {
    if (disposed) return
    value.stop()
    const from = parseFloat(String(value.get()))
    const to = parseFloat(String(target))
    if (from === to) return
    value.start((onComplete) => new JSAnimation({
      keyframes: [from, to],
      velocity: value.getVelocity(),
      type: "spring",
      restDelta: 0.001,
      restSpeed: 0.01,
      ...options,
      onUpdate: (latest) => setter(parse(latest)),
      onComplete,
    }))
  }
  value.attach((latest, set) => {
    target = latest
    setter = set
    frame.postRender(start)
  }, stop)
  const unsubscribe = isMotionValue(source)
    ? source.on("change", (latest) => value.set(parse(latest)))
    : undefined

  value.on("destroy", () => {
    disposed = true
    unsubscribe?.()
    stop()
  })
  onCleanup(() => value.destroy())

  return value
}
