import { AnyResolvedKeyframe, buildHTMLStyles, isForcedMotionValue, isMotionValue, MotionValue } from "motion-dom"
import type { MotionProps } from "../../motion/types"
import type { ResolvedValues } from "../types"
import { createHtmlRenderState } from "./utils/create-render-state"
import { toSolidStyle } from "../dom/style"

export function copyRawValuesOnly(
  target: ResolvedValues,
  source: { [key: string]: AnyResolvedKeyframe | MotionValue },
  props: MotionProps,
) {
  for (const key in source) {
    if (!isMotionValue(source[key]) && !isForcedMotionValue(key, props)) {
      target[key] = source[key] as AnyResolvedKeyframe
    }
  }
}

function resolveInitialMotionValues({ transformTemplate }: MotionProps, visualState: ResolvedValues) {
  const state = createHtmlRenderState()
  buildHTMLStyles(state, visualState, transformTemplate)
  return { ...state.vars, ...state.style }
}

function resolveStyle(props: MotionProps, visualState: ResolvedValues) {
  const styleProp = props.style || {}
  const style: ResolvedValues = {}

  copyRawValuesOnly(style, styleProp as any, props)
  Object.assign(style, resolveInitialMotionValues(props, visualState))

  return style
}

export function resolveHTMLProps(props: MotionProps, visualState: ResolvedValues) {
  const htmlProps: Record<string, unknown> = {}
  const style = resolveStyle(props, visualState)

  if (props.drag && (props as any).dragListener !== false) {
    ;(htmlProps as any).draggable = false
    ;(style as any).userSelect = (style as any).WebkitUserSelect = (style as any).WebkitTouchCallout = "none"
    ;(style as any).touchAction = props.drag === true ? "none" : `pan-${props.drag === "x" ? "y" : "x"}`
  }

  if ((props as any).tabIndex === undefined && ((props as any).onTap || (props as any).onTapStart || props.whileTap)) {
    ;(htmlProps as any).tabIndex = 0
  }

  ;(htmlProps as any).style = toSolidStyle(style)
  return htmlProps
}
