import type { MotionValue, MotionValueEventCallbacks } from "motion-dom"
import { onCleanup } from "solid-js"

/** Subscribe during setup and unsubscribe when the Solid owner is disposed. */
export function useMotionValueEvent<V, EventName extends keyof MotionValueEventCallbacks<V>>(
  value: MotionValue<V>,
  event: EventName,
  callback: MotionValueEventCallbacks<V>[EventName],
) {
  onCleanup(value.on(event, callback))
}
