import { createContext, type Accessor } from "solid-js"
import type { PresenceContextProps as MotionDomPresenceContextProps } from "motion-dom"
import type { VariantLabels } from "../motion/types"

export type { MotionDomPresenceContextProps as ResolvedPresenceContextProps }

export interface PresenceContextProps {
  id: Accessor<string>
  isPresent: Accessor<boolean>
  register?: (id: string | number) => () => void
  onExitComplete?: (id: string | number) => void
  initial: Accessor<false | VariantLabels | undefined>
  custom: Accessor<any>
}

export const PresenceContext = createContext<PresenceContextProps | null>(null)
