import { createEffect, createSignal } from "solid-js"
import type { MotionProps } from "../../motion/types"
import type { MotionContextProps } from "../MotionContext"
import { getCurrentTreeVariants } from "./utils"

export function createMotionContext<Instance>(
  props: MotionProps,
  parentContext: MotionContextProps,
): MotionContextProps<Instance> {
  const [initial, setInitial] = createSignal<MotionContextProps["initial"]>()
  const [animate, setAnimate] = createSignal<MotionContextProps["animate"]>()

  createEffect(() => {
    const variants = getCurrentTreeVariants(props, parentContext)
    setInitial(variants.initial)
    setAnimate(variants.animate)
  })


  return {
    get initial() {
      return initial()
    },
    get animate() {
      return animate()
    },
  }
}
