import { cancelFrame, frame, type MotionValue } from "motion-dom"
import { onCleanup } from "solid-js"
import { useMotionValue } from "./use-motion-value"
import { useMotionValueEvent } from "./use-motion-value-event"

/** Track velocity, including its return to zero after the source stops changing. */
export function useVelocity(value: MotionValue<number>): MotionValue<number> {
  const velocity = useMotionValue(value.getVelocity())
  const update = () => {
    const latest = value.getVelocity()
    velocity.set(latest)
    if (latest) frame.update(update)
  }

  useMotionValueEvent(value, "change", () => frame.update(update, false, true))
  onCleanup(() => cancelFrame(update))
  return velocity
}
