import { HTMLProjectionNode, type VisualElement } from "motion-dom"
import type { MotionProps } from "../types"

export function prepareDragProjection(node: VisualElement<HTMLElement | SVGElement>, props: MotionProps) {
  if (node.projection || !(props.drag || props.dragControls)) return
  // Drag constraints use Motion's geometry measurement, without enabling layout
  // animation or shared layout IDs. Non-draggable elements pay no projection cost.
  node.projection = new HTMLProjectionNode(node.latestValues, node.parent?.projection)
  node.projection.setOptions({
    visualElement: node,
    alwaysMeasureLayout: true,
    layout: false,
    animationType: "both",
  })
  if (node.current) node.projection.mount(node.current)
}
