import { createSignal, onCleanup, type Accessor } from "solid-js"

/**
 * Reactive device preference. Read as `shouldReduceMotion()` in tracked code.
 * Returns null on the server or when matchMedia is unavailable.
 */
export function useReducedMotion(): Accessor<boolean | null> {
  if (typeof window === "undefined" || !window.matchMedia) return () => null

  const media = window.matchMedia("(prefers-reduced-motion: reduce)")
  const [reduced, setReduced] = createSignal(media.matches)
  const update = () => setReduced(media.matches)
  media.addEventListener("change", update)
  onCleanup(() => media.removeEventListener("change", update))
  return reduced
}
